import type { InputSource } from '../../types/camera';

interface Car {
  x: number;
  y: number;
  speed: number;
  lane: number;
  isHeadlight: boolean;
  length: number;
  color: string;
}

interface WaterParticle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  alpha: number;
}

interface Pedestrian {
  x: number;
  y: number;
  targetX: number;
  targetY: number;
  speed: number;
  color: string;
  size: number;
}

export class SyntheticSceneGenerator {
  private readonly canvas: HTMLCanvasElement;
  private readonly ctx: CanvasRenderingContext2D;
  private readonly width: number;
  private readonly height: number;

  private cars: Car[] = [];
  private waterParticles: WaterParticle[] = [];
  private pedestrians: Pedestrian[] = [];
  private lastTime = 0;

  constructor(width = 1280, height = 720) {
    this.width = width;
    this.height = height;
    this.canvas = document.createElement('canvas');
    this.canvas.width = width;
    this.canvas.height = height;

    const ctx = this.canvas.getContext('2d', { alpha: false });
    if (!ctx) throw new Error('2D context not available for synthetic generator');
    this.ctx = ctx;

    this.initEntities();
  }

  public getCanvas(): HTMLCanvasElement {
    return this.canvas;
  }

  private initEntities(): void {
    // 1. Initialize Highway Traffic
    this.cars = [];
    for (let i = 0; i < 28; i++) {
      const isEastbound = Math.random() > 0.5;
      this.cars.push({
        x: Math.random() * this.width,
        y: isEastbound ? this.height * 0.58 + (i % 3) * 22 : this.height * 0.72 + (i % 3) * 22,
        speed: (isEastbound ? 1 : -1) * (180 + Math.random() * 120),
        lane: i % 3,
        isHeadlight: isEastbound,
        length: 24 + Math.random() * 16,
        color: isEastbound ? '#FFF8E7' : '#FF2A2A'
      });
    }

    // 2. Initialize Waterfall Particles
    this.waterParticles = [];
    for (let i = 0; i < 350; i++) {
      this.waterParticles.push({
        x: this.width * 0.42 + Math.random() * (this.width * 0.16),
        y: this.height * 0.1 + Math.random() * (this.height * 0.8),
        vx: (Math.random() - 0.5) * 30,
        vy: 240 + Math.random() * 320,
        size: 2 + Math.random() * 4,
        alpha: 0.6 + Math.random() * 0.4
      });
    }

    // 3. Initialize Walking Pedestrians
    this.pedestrians = [];
    const colors = ['#E63946', '#F1FAEE', '#A8DADC', '#457B9D', '#1D3557', '#F4A261', '#E76F51', '#9B5DE5'];
    for (let i = 0; i < 32; i++) {
      this.pedestrians.push({
        x: Math.random() * this.width,
        y: this.height * 0.45 + Math.random() * (this.height * 0.45),
        targetX: Math.random() * this.width,
        targetY: this.height * 0.45 + Math.random() * (this.height * 0.45),
        speed: 25 + Math.random() * 45,
        color: colors[i % colors.length],
        size: 14 + Math.random() * 8
      });
    }
  }

  public update(source: InputSource, currentTime: number): void {
    if (this.lastTime === 0) this.lastTime = currentTime;
    const dt = Math.min((currentTime - this.lastTime) / 1000, 0.1);
    this.lastTime = currentTime;

    const ctx = this.ctx;
    const w = this.width;
    const h = this.height;

    switch (source) {
      case 'SIM_TRAFFIC':
        this.renderNightTraffic(ctx, w, h, dt);
        break;
      case 'SIM_WATERFALL':
        this.renderWaterfall(ctx, w, h, dt);
        break;
      case 'SIM_PLAZA':
        this.renderPlaza(ctx, w, h, dt);
        break;
      default:
        break;
    }
  }

  private renderNightTraffic(ctx: CanvasRenderingContext2D, w: number, h: number, dt: number): void {
    // Dark nocturnal city backdrop
    const grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, '#05070D');
    grad.addColorStop(0.5, '#0B0F1A');
    grad.addColorStop(1, '#080A0F');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);

    // Distant skyscraper silhouettes with illuminated windows
    ctx.fillStyle = '#06080F';
    const buildingWidths = [60, 90, 75, 110, 85, 130, 95, 70, 100, 80, 120, 90, 140];
    let curX = 0;
    for (let i = 0; i < buildingWidths.length && curX < w; i++) {
      const bw = buildingWidths[i];
      const bh = 180 + ((i * 37) % 160);
      ctx.fillRect(curX, h * 0.52 - bh, bw, bh);

      // Windows
      ctx.fillStyle = '#FFDD80';
      for (let wy = h * 0.52 - bh + 15; wy < h * 0.5; wy += 20) {
        for (let wx = curX + 10; wx < curX + bw - 10; wx += 16) {
          if ((wx * wy + i) % 7 > 2) {
            ctx.globalAlpha = 0.4 + (((wx + wy) % 5) * 0.1);
            ctx.fillRect(wx, wy, 6, 8);
          }
        }
      }
      ctx.fillStyle = '#06080F';
      ctx.globalAlpha = 1.0;
      curX += bw + 8;
    }

    // Curved highway asphalt
    ctx.fillStyle = '#101217';
    ctx.beginPath();
    ctx.moveTo(0, h * 0.55);
    ctx.bezierCurveTo(w * 0.35, h * 0.54, w * 0.65, h * 0.58, w, h * 0.55);
    ctx.lineTo(w, h * 0.88);
    ctx.bezierCurveTo(w * 0.65, h * 0.90, w * 0.35, h * 0.86, 0, h * 0.88);
    ctx.closePath();
    ctx.fill();

    // Road dashed dividing lines
    ctx.strokeStyle = '#3A3F4D';
    ctx.lineWidth = 2;
    ctx.setLineDash([16, 24]);
    ctx.beginPath();
    ctx.moveTo(0, h * 0.68);
    ctx.bezierCurveTo(w * 0.35, h * 0.67, w * 0.65, h * 0.71, w, h * 0.68);
    ctx.stroke();
    ctx.setLineDash([]);

    // Update and draw cars with luminous headlights and red tail lights
    for (const car of this.cars) {
      car.x += car.speed * dt;
      if (car.speed > 0 && car.x > w + 60) car.x = -60;
      if (car.speed < 0 && car.x < -60) car.x = w + 60;

      // Car body
      ctx.fillStyle = '#181A20';
      ctx.fillRect(car.x - car.length * 0.5, car.y - 7, car.length, 14);

      if (car.isHeadlight) {
        // Bright white/amber headlights with forward beam glow
        const glow = ctx.createRadialGradient(car.x + car.length * 0.5, car.y, 2, car.x + car.length * 0.5 + 20, car.y, 45);
        glow.addColorStop(0, 'rgba(255, 250, 230, 1.0)');
        glow.addColorStop(0.3, 'rgba(255, 220, 140, 0.6)');
        glow.addColorStop(1, 'rgba(255, 200, 100, 0.0)');
        ctx.fillStyle = glow;
        ctx.beginPath();
        ctx.arc(car.x + car.length * 0.5 + 8, car.y, 35, -Math.PI * 0.4, Math.PI * 0.4);
        ctx.fill();

        // Core bright bulbs
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(car.x + car.length * 0.5 - 2, car.y - 5, 4, 3);
        ctx.fillRect(car.x + car.length * 0.5 - 2, car.y + 2, 4, 3);
      } else {
        // Vivid Red Taillights with rear flare
        const glow = ctx.createRadialGradient(car.x - car.length * 0.5, car.y, 2, car.x - car.length * 0.5 - 12, car.y, 32);
        glow.addColorStop(0, 'rgba(255, 40, 40, 1.0)');
        glow.addColorStop(0.4, 'rgba(220, 10, 10, 0.5)');
        glow.addColorStop(1, 'rgba(180, 0, 0, 0.0)');
        ctx.fillStyle = glow;
        ctx.beginPath();
        ctx.arc(car.x - car.length * 0.5 - 4, car.y, 25, Math.PI * 0.6, Math.PI * 1.4);
        ctx.fill();

        // Core bright red bulbs
        ctx.fillStyle = '#FF4D4D';
        ctx.fillRect(car.x - car.length * 0.5 - 2, car.y - 5, 4, 3);
        ctx.fillRect(car.x - car.length * 0.5 - 2, car.y + 2, 4, 3);
      }
    }
  }

  private renderWaterfall(ctx: CanvasRenderingContext2D, w: number, h: number, dt: number): void {
    // Mountain Forest Sky
    const skyGrad = ctx.createLinearGradient(0, 0, 0, h * 0.4);
    skyGrad.addColorStop(0, '#5A7282');
    skyGrad.addColorStop(1, '#8FA6B5');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, w, h * 0.4);

    // Granite Mountain Cliffs (Left & Right)
    ctx.fillStyle = '#2A3036';
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(w * 0.42, 0);
    ctx.lineTo(w * 0.40, h * 0.35);
    ctx.lineTo(w * 0.37, h * 0.75);
    ctx.lineTo(w * 0.30, h);
    ctx.lineTo(0, h);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#23282D';
    ctx.beginPath();
    ctx.moveTo(w, 0);
    ctx.lineTo(w * 0.60, 0);
    ctx.lineTo(w * 0.62, h * 0.35);
    ctx.lineTo(w * 0.64, h * 0.70);
    ctx.lineTo(w * 0.72, h);
    ctx.lineTo(w, h);
    ctx.closePath();
    ctx.fill();

    // Dark evergreen pines on cliffs
    ctx.fillStyle = '#18241D';
    for (let px = 20; px < w * 0.36; px += 45) {
      this.drawPineTree(ctx, px, h * 0.28 + ((px * 17) % 60), 30);
    }
    for (let px = w * 0.66; px < w - 20; px += 50) {
      this.drawPineTree(ctx, px, h * 0.26 + ((px * 23) % 70), 32);
    }

    // Waterfall Channel Base
    ctx.fillStyle = '#1A2933';
    ctx.fillRect(w * 0.40, 0, w * 0.21, h * 0.85);

    // Flowing churning water particles
    for (const p of this.waterParticles) {
      p.y += p.vy * dt;
      p.x += p.vx * dt;

      // Turbulence as water cascades
      p.vx += (Math.random() - 0.5) * 40 * dt;

      if (p.y > h * 0.82) {
        p.y = h * 0.05 + Math.random() * 30;
        p.x = w * 0.41 + Math.random() * (w * 0.18);
        p.vx = (Math.random() - 0.5) * 20;
      }

      ctx.fillStyle = `rgba(235, 245, 255, ${p.alpha})`;
      ctx.fillRect(p.x, p.y, p.size, p.size * 3.5);
    }

    // Lower pool with mist and waves
    const poolGrad = ctx.createLinearGradient(0, h * 0.78, 0, h);
    poolGrad.addColorStop(0, '#264253');
    poolGrad.addColorStop(1, '#162833');
    ctx.fillStyle = poolGrad;
    ctx.fillRect(0, h * 0.8, w, h * 0.2);

    // Churning water foam at bottom
    ctx.fillStyle = 'rgba(255, 255, 255, 0.45)';
    for (let i = 0; i < 16; i++) {
      const fx = w * 0.38 + i * 18 + Math.sin(this.lastTime * 0.005 + i) * 12;
      const fy = h * 0.81 + Math.cos(this.lastTime * 0.006 + i) * 8;
      ctx.beginPath();
      ctx.ellipse(fx, fy, 28, 10, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  private drawPineTree(ctx: CanvasRenderingContext2D, x: number, y: number, height: number): void {
    ctx.beginPath();
    ctx.moveTo(x, y - height);
    ctx.lineTo(x + height * 0.4, y);
    ctx.lineTo(x - height * 0.4, y);
    ctx.closePath();
    ctx.fill();
  }

  private renderPlaza(ctx: CanvasRenderingContext2D, w: number, h: number, dt: number): void {
    // Historic European Plaza Sky & Golden Hour Sunlight
    const skyGrad = ctx.createLinearGradient(0, 0, 0, h * 0.5);
    skyGrad.addColorStop(0, '#4A6984');
    skyGrad.addColorStop(0.7, '#D4A373');
    skyGrad.addColorStop(1, '#FAEDCD');
    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, w, h * 0.5);

    // Historic Monumental Palace Architecture (Stationary Background)
    ctx.fillStyle = '#C2B69D';
    ctx.fillRect(w * 0.15, h * 0.18, w * 0.70, h * 0.32);

    // Classical Colonnade Pillars
    ctx.fillStyle = '#8C7B65';
    for (let c = w * 0.18; c < w * 0.82; c += 42) {
      ctx.fillRect(c, h * 0.25, 14, h * 0.25);
    }

    // Pediment Triangle & Arch
    ctx.fillStyle = '#A3927A';
    ctx.beginPath();
    ctx.moveTo(w * 0.5, h * 0.08);
    ctx.lineTo(w * 0.68, h * 0.18);
    ctx.lineTo(w * 0.32, h * 0.18);
    ctx.closePath();
    ctx.fill();

    // Cobblestone Plaza Ground
    const plazaGrad = ctx.createLinearGradient(0, h * 0.5, 0, h);
    plazaGrad.addColorStop(0, '#6C584C');
    plazaGrad.addColorStop(1, '#4A3B32');
    ctx.fillStyle = plazaGrad;
    ctx.fillRect(0, h * 0.5, w, h * 0.5);

    // Central Stone Fountain (Stationary)
    ctx.fillStyle = '#54463C';
    ctx.beginPath();
    ctx.ellipse(w * 0.5, h * 0.72, 85, 28, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#8AB0AB';
    ctx.beginPath();
    ctx.ellipse(w * 0.5, h * 0.72, 70, 20, 0, 0, Math.PI * 2);
    ctx.fill();

    // Update and render walking pedestrians (transient moving objects)
    for (const p of this.pedestrians) {
      const dx = p.targetX - p.x;
      const dy = p.targetY - p.y;
      const dist = Math.hypot(dx, dy);

      if (dist < 8) {
        // Pick new random destination across plaza
        p.targetX = Math.random() * w;
        p.targetY = h * 0.52 + Math.random() * (h * 0.42);
      } else {
        p.x += (dx / dist) * p.speed * dt;
        p.y += (dy / dist) * p.speed * dt;
      }

      // Pedestrian silhouette & shadow
      // Drop shadow
      ctx.fillStyle = 'rgba(20, 15, 10, 0.4)';
      ctx.beginPath();
      ctx.ellipse(p.x, p.y + p.size * 0.45, p.size * 0.5, p.size * 0.2, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y - p.size * 0.5, p.size * 0.22, 0, Math.PI * 2); // Head
      ctx.fill();

      ctx.fillRect(p.x - p.size * 0.2, p.y - p.size * 0.3, p.size * 0.4, p.size * 0.65); // Torso/Coat
    }
  }
}
