import type { LongExposureEngine } from '../../core/engine/LongExposureEngine';
import type { CaptureProgress, HistogramData } from '../../types/camera';

export class ViewfinderOverlay {
  private readonly container: HTMLElement;
  private engine: LongExposureEngine | null = null;

  private canvas: HTMLCanvasElement | null = null;
  private histCanvas: HTMLCanvasElement | null = null;
  private histCtx: CanvasRenderingContext2D | null = null;

  private exposureOverlay: HTMLElement | null = null;
  private countdownCircle: SVGCircleElement | null = null;
  private countdownNumber: HTMLElement | null = null;
  private stabBadge: HTMLElement | null = null;

  constructor(engine?: LongExposureEngine) {
    this.container = document.createElement('div');
    this.container.className = 'viewfinder-container';
    this.render();
    if (engine) {
      this.bindEngine(engine);
    }
  }

  public bindEngine(engine: LongExposureEngine): void {
    this.engine = engine;
    this.initSubscriptions();
  }

  public getElement(): HTMLElement {
    return this.container;
  }

  public getCanvas(): HTMLCanvasElement {
    if (!this.canvas) throw new Error('GL Canvas not initialized');
    return this.canvas;
  }

  private render(): void {
    this.container.innerHTML = `
      <canvas id="glCanvas" width="1280" height="720"></canvas>

      <div class="viewfinder-hud">
        <!-- Rule of thirds composition grid -->
        <div class="grid-lines">
          <div class="grid-cell"></div>
          <div class="grid-cell"></div>
          <div class="grid-cell"></div>
          <div class="grid-cell"></div>
          <div class="grid-cell"></div>
          <div class="grid-cell"></div>
          <div class="grid-cell"></div>
          <div class="grid-cell"></div>
          <div class="grid-cell"></div>
        </div>

        <!-- Electronic Horizon Level Indicator -->
        <div class="horizon-level level-balanced" id="horizonLevel"></div>

        <!-- Real-time Live RGB Histogram -->
        <div class="histogram-box">
          <canvas id="histCanvas" width="80" height="40"></canvas>
        </div>

        <!-- Handheld AI Stabilization Telemetry -->
        <div class="stab-telemetry">
          <div class="stab-indicator-dot"></div>
          <span id="stabBadge">AI OPTICAL LOCKED 99%</span>
        </div>
      </div>

      <!-- Live Progressive Exposure Countdown Overlay -->
      <div class="exposure-overlay" id="exposureOverlay">
        <div class="countdown-ring-box">
          <svg class="countdown-svg" viewBox="0 0 100 100">
            <circle class="countdown-circle-bg" cx="50" cy="50" r="44"></circle>
            <circle class="countdown-circle-prog" id="countdownCircle" cx="50" cy="50" r="44" stroke-dasharray="276.46" stroke-dashoffset="0"></circle>
          </svg>
          <div class="countdown-number" id="countdownNumber">3.0s</div>
        </div>
        <div class="live-forming-badge" id="liveBadge">Progressive Exposure Forming</div>
      </div>
    `;

    this.canvas = this.container.querySelector<HTMLCanvasElement>('#glCanvas');
    this.histCanvas = this.container.querySelector<HTMLCanvasElement>('#histCanvas');
    if (this.histCanvas) {
      this.histCtx = this.histCanvas.getContext('2d');
    }

    this.exposureOverlay = this.container.querySelector<HTMLElement>('#exposureOverlay');
    this.countdownCircle = this.container.querySelector<SVGCircleElement>('#countdownCircle');
    this.countdownNumber = this.container.querySelector<HTMLElement>('#countdownNumber');
    this.stabBadge = this.container.querySelector<HTMLElement>('#stabBadge');
  }

  private initSubscriptions(): void {
    if (!this.engine) return;
    const circumference = 2 * Math.PI * 44; // ~276.46

    this.engine.subscribeProgress((progress: CaptureProgress) => {
      if (progress.state === 'EXPOSING') {
        this.exposureOverlay?.classList.add('active');

        // Update progress ring
        if (this.countdownCircle) {
          const offset = circumference * (1 - progress.progressPercent / 100);
          this.countdownCircle.style.strokeDashoffset = String(offset);
        }

        // Update countdown text
        if (this.countdownNumber) {
          if (progress.targetSeconds > 0) {
            const remaining = Math.max(0, progress.targetSeconds - progress.elapsedSeconds);
            this.countdownNumber.innerText = `${remaining.toFixed(1)}s`;
          } else {
            // Bulb mode
            this.countdownNumber.innerText = `${progress.elapsedSeconds.toFixed(1)}s`;
          }
        }

        if (this.stabBadge) {
          const confidence = Math.min(99, Math.floor(96 + (progress.frameCount % 4)));
          this.stabBadge.innerText = `AI OPTICAL LOCKED ${confidence}%`;
        }
      } else {
        this.exposureOverlay?.classList.remove('active');
      }
    });

    this.engine.subscribeHistogram((data: HistogramData) => {
      this.renderHistogram(data);
    });
  }

  private renderHistogram(data: HistogramData): void {
    if (!this.histCtx || !this.histCanvas) return;
    const ctx = this.histCtx;
    const w = this.histCanvas.width;
    const h = this.histCanvas.height;

    ctx.clearRect(0, 0, w, h);

    const max = Math.max(1, data.max);
    const step = 256 / w;

    // Draw combined RGB histogram curves
    const channels = [
      { hist: data.r, color: 'rgba(235, 68, 90, 0.7)' },
      { hist: data.g, color: 'rgba(45, 211, 111, 0.7)' },
      { hist: data.b, color: 'rgba(56, 128, 255, 0.7)' }
    ];

    channels.forEach(({ hist, color }) => {
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(0, h);

      for (let x = 0; x < w; x++) {
        const binIndex = Math.min(255, Math.floor(x * step));
        const val = hist[binIndex] || 0;
        const barHeight = (val / max) * h * 0.92;
        ctx.lineTo(x, h - barHeight);
      }

      ctx.lineTo(w, h);
      ctx.closePath();
      ctx.fill();
    });
  }
}
