import './ui/styles/main.css';
import { LongExposureEngine } from './core/engine/LongExposureEngine';
import { HeaderBar } from './ui/components/HeaderBar';
import { ViewfinderOverlay } from './ui/components/ViewfinderOverlay';
import { ModeDial } from './ui/components/ModeDial';
import { ShutterArea } from './ui/components/ShutterArea';
import { BeforeAfterModal } from './ui/components/BeforeAfterModal';
import { PricingModal } from './ui/components/PricingModal';
import type { CaptureResult } from './types/camera';

class LuminaShutterApp {
  private readonly appRoot: HTMLElement;
  private engine!: LongExposureEngine;
  private headerBar!: HeaderBar;
  private viewfinder!: ViewfinderOverlay;
  private modeDial!: ModeDial;
  private shutterArea!: ShutterArea;
  private beforeAfterModal!: BeforeAfterModal;
  private pricingModal!: PricingModal;

  private latestResult: CaptureResult | null = null;

  constructor() {
    const root = document.getElementById('app');
    if (!root) throw new Error('#app root element not found');
    this.appRoot = root;

    this.init();
  }

  private init(): void {
    // 1. Modals
    this.beforeAfterModal = new BeforeAfterModal();
    this.pricingModal = new PricingModal();

    // 2. Viewfinder & WebGL Canvas
    this.viewfinder = new ViewfinderOverlay();
    const canvas = this.viewfinder.getCanvas();

    // 3. Engine attached to Viewfinder Canvas
    this.engine = new LongExposureEngine(canvas);
    this.viewfinder.bindEngine(this.engine);

    // 4. Header Bar
    this.headerBar = new HeaderBar(this.engine, () => {
      this.pricingModal.open();
    });

    // 5. Mode Dial & Shutter Area
    this.modeDial = new ModeDial(this.engine);
    this.shutterArea = new ShutterArea(this.engine, () => {
      if (this.latestResult) {
        this.beforeAfterModal.open(this.latestResult);
      }
    });

    // 6. Mount to DOM
    this.appRoot.innerHTML = '';
    this.appRoot.appendChild(this.headerBar.getElement());
    this.appRoot.appendChild(this.viewfinder.getElement());
    this.appRoot.appendChild(this.modeDial.getElement());
    this.appRoot.appendChild(this.shutterArea.getElement());

    this.appRoot.appendChild(this.beforeAfterModal.getElement());
    this.appRoot.appendChild(this.pricingModal.getElement());

    this.initEventWiring();
  }

  private initEventWiring(): void {
    // When an exposure completes, update shutter thumbnail and show Before/After modal
    this.engine.subscribeResult((result: CaptureResult) => {
      this.latestResult = result;
      this.shutterArea.setLastResult(result);
      this.beforeAfterModal.open(result);
    });

    // Keyboard shortcuts for Leica-like pro workflow:
    // Space: Shutter trigger / stop
    // 1, 2, 3: Modes (Light Trails, Silky Water, Crowd Eraser)
    window.addEventListener('keydown', (e) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLSelectElement) return;

      if (e.code === 'Space') {
        e.preventDefault();
        if (this.engine.getState() === 'EXPOSING') {
          this.engine.stopExposure();
        } else {
          this.engine.startExposure();
        }
      } else if (e.key === '1') {
        this.engine.setMode('LIGHT_TRAILS');
        this.syncModeUI('LIGHT_TRAILS');
      } else if (e.key === '2') {
        this.engine.setMode('SILKY_WATER');
        this.syncModeUI('SILKY_WATER');
      } else if (e.key === '3') {
        this.engine.setMode('CROWD_ERASER');
        this.syncModeUI('CROWD_ERASER');
      }
    });
  }

  private syncModeUI(mode: string): void {
    const tabs = document.querySelectorAll<HTMLElement>('.mode-tab');
    tabs.forEach((tab) => tab.classList.toggle('active', tab.dataset.mode === mode));
  }
}

// Bootstrap on DOM ready
window.addEventListener('DOMContentLoaded', () => {
  new LuminaShutterApp();
});
