import type { InputSource } from '../../types/camera';
import { SyntheticSceneGenerator } from './SyntheticSceneGenerator';

export class CameraManager {
  private activeSource: InputSource = 'SIM_TRAFFIC';
  private videoElement: HTMLVideoElement | null = null;
  private mediaStream: MediaStream | null = null;
  private syntheticGenerator: SyntheticSceneGenerator;
  private isCameraAvailable = false;
  private torchEnabled = false;

  constructor() {
    this.syntheticGenerator = new SyntheticSceneGenerator(1280, 720);
    this.initVideoElement();
  }

  private initVideoElement(): void {
    const video = document.createElement('video');
    video.autoplay = true;
    video.muted = true;
    video.playsInline = true;
    this.videoElement = video;
  }

  public async setInputSource(source: InputSource): Promise<void> {
    this.activeSource = source;

    if (source === 'LIVE_CAMERA') {
      await this.startLiveCamera();
    } else {
      this.stopLiveCamera();
    }
  }

  public getActiveSource(): InputSource {
    return this.activeSource;
  }

  public async startLiveCamera(): Promise<boolean> {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      console.warn('getUserMedia not supported on this platform. Falling back to simulation.');
      this.activeSource = 'SIM_TRAFFIC';
      return false;
    }

    try {
      this.stopLiveCamera();

      const constraints: MediaStreamConstraints = {
        audio: false,
        video: {
          facingMode: { ideal: 'environment' },
          width: { ideal: 1920, min: 1280 },
          height: { ideal: 1080, min: 720 },
          frameRate: { ideal: 60, min: 30 }
        }
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      this.mediaStream = stream;

      if (this.videoElement) {
        this.videoElement.srcObject = stream;
        await this.videoElement.play();
      }

      this.isCameraAvailable = true;
      this.activeSource = 'LIVE_CAMERA';
      return true;
    } catch (err) {
      console.warn('Could not access live camera. Defaulting to high-res simulation.', err);
      this.isCameraAvailable = false;
      this.activeSource = 'SIM_TRAFFIC';
      return false;
    }
  }

  public stopLiveCamera(): void {
    if (this.mediaStream) {
      this.mediaStream.getTracks().forEach((track) => track.stop());
      this.mediaStream = null;
    }
    if (this.videoElement) {
      this.videoElement.srcObject = null;
    }
    this.torchEnabled = false;
  }

  public async toggleTorch(enable?: boolean): Promise<boolean> {
    if (!this.mediaStream) return false;
    const track = this.mediaStream.getVideoTracks()[0];
    if (!track) return false;

    const target = enable !== undefined ? enable : !this.torchEnabled;

    try {
      const capabilities = track.getCapabilities?.() as { torch?: boolean } | undefined;
      if (capabilities && capabilities.torch) {
        await (track as MediaStreamTrack & { applyConstraints: (c: unknown) => Promise<void> }).applyConstraints({
          advanced: [{ torch: target }]
        });
        this.torchEnabled = target;
        return this.torchEnabled;
      }
    } catch (e) {
      console.warn('Torch constraint not supported', e);
    }
    return false;
  }

  /**
   * Get the active texture source (either live HTMLVideoElement or Synthetic canvas)
   */
  public getFrameSource(timestamp: number): TexImageSource {
    if (this.activeSource === 'LIVE_CAMERA' && this.videoElement && this.videoElement.readyState >= 2) {
      return this.videoElement;
    }

    // Update procedural scenario
    this.syntheticGenerator.update(this.activeSource, timestamp);
    return this.syntheticGenerator.getCanvas();
  }

  public getDimensions(): { width: number; height: number } {
    if (this.activeSource === 'LIVE_CAMERA' && this.videoElement && this.videoElement.videoWidth > 0) {
      return {
        width: this.videoElement.videoWidth,
        height: this.videoElement.videoHeight
      };
    }
    return { width: 1280, height: 720 };
  }

  public getIsCameraAvailable(): boolean {
    return this.isCameraAvailable;
  }

  public destroy(): void {
    this.stopLiveCamera();
  }
}
