import type { StabilizationMode, StabilizationOffset } from '../../types/camera';

export class HandheldStabilizer {
  private mode: StabilizationMode = 'AI_OPTICAL';
  private gyroAvailable = false;

  // Real device gyro tracking
  private currentGyroAngle = 0;
  private currentGyroDx = 0;
  private currentGyroDy = 0;

  // Filtered offsets
  private filteredDx = 0;
  private filteredDy = 0;
  private filteredAngle = 0;

  constructor() {
    this.initSensors();
  }

  private initSensors(): void {
    if (typeof window !== 'undefined' && 'DeviceMotionEvent' in window) {
      window.addEventListener(
        'devicemotion',
        (event) => {
          if (!event.rotationRate) return;
          this.gyroAvailable = true;

          // Convert rotational rate to pixel displacement approximation
          const alpha = event.rotationRate.alpha ?? 0;
          const beta = event.rotationRate.beta ?? 0;
          const gamma = event.rotationRate.gamma ?? 0;

          const sensitivity = 0.0004;
          this.currentGyroAngle = (gamma * Math.PI) / 180 * 0.1;
          this.currentGyroDx = beta * sensitivity;
          this.currentGyroDy = alpha * sensitivity;
        },
        { passive: true }
      );
    }
  }

  public setMode(mode: StabilizationMode): void {
    this.mode = mode;
  }

  public getMode(): StabilizationMode {
    return this.mode;
  }

  public isGyroSupported(): boolean {
    return this.gyroAvailable;
  }

  public reset(): void {
    this.filteredDx = 0;
    this.filteredDy = 0;
    this.filteredAngle = 0;
  }

  /**
   * Compute the frame-to-frame stabilization alignment offset
   */
  public computeOffset(_timestamp: number, isExposing: boolean): StabilizationOffset {
    if (this.mode === 'OFF' || !this.gyroAvailable) {
      return { dx: 0, dy: 0, angle: 0, confidence: 0.99 };
    }

    // When hardware gyro is active, apply counter-shift alignment
    const targetDx = this.currentGyroDx;
    const targetDy = this.currentGyroDy;
    const targetAngle = this.currentGyroAngle;

    const counterFactor = isExposing ? -1.0 : -0.8;
    const smoothing = 0.85;

    this.filteredDx = this.filteredDx * smoothing + targetDx * counterFactor * (1 - smoothing);
    this.filteredDy = this.filteredDy * smoothing + targetDy * counterFactor * (1 - smoothing);
    this.filteredAngle = this.filteredAngle * smoothing + targetAngle * counterFactor * (1 - smoothing);

    const movementMagnitude = Math.hypot(this.filteredDx, this.filteredDy) * 100;
    const confidence = Math.max(0.92, Math.min(0.999, 1.0 - movementMagnitude * 0.05));

    return {
      dx: this.filteredDx,
      dy: this.filteredDy,
      angle: this.filteredAngle,
      confidence
    };
  }
}
