import { ICONS } from '../icons';
import type { LongExposureEngine } from '../../core/engine/LongExposureEngine';
import type { ExposureMode } from '../../types/camera';

export class ModeDial {
  private readonly container: HTMLElement;
  private readonly engine: LongExposureEngine;

  constructor(engine: LongExposureEngine) {
    this.engine = engine;
    this.container = document.createElement('div');
    this.container.className = 'mode-dial-strip';
    this.render();
  }

  public getElement(): HTMLElement {
    return this.container;
  }

  private render(): void {
    const currentMode = this.engine.getMode();

    this.container.innerHTML = `
      <div class="mode-tab ${currentMode === 'LIGHT_TRAILS' ? 'active' : ''}" data-mode="LIGHT_TRAILS">
        ${ICONS.lightTrails}
        <span>LIGHT TRAILS</span>
      </div>
      <div class="mode-tab ${currentMode === 'SILKY_WATER' ? 'active' : ''}" data-mode="SILKY_WATER">
        ${ICONS.silkyWater}
        <span>SILKY WATER</span>
      </div>
      <div class="mode-tab ${currentMode === 'CROWD_ERASER' ? 'active' : ''}" data-mode="CROWD_ERASER">
        ${ICONS.crowdEraser}
        <span>CROWD ERASER</span>
      </div>
    `;

    this.attachEvents();
  }

  private attachEvents(): void {
    const tabs = this.container.querySelectorAll<HTMLElement>('.mode-tab');
    tabs.forEach((tab) => {
      tab.addEventListener('click', async () => {
        const mode = tab.dataset.mode as ExposureMode;
        if (!mode) return;

        this.engine.setMode(mode);

        tabs.forEach((t) => t.classList.toggle('active', t === tab));

        // Auto-switch simulation scene if in simulation mode for seamless instant showcase
        const cam = this.engine.getCameraManager();
        const activeSrc = cam.getActiveSource();
        if (activeSrc !== 'LIVE_CAMERA') {
          if (mode === 'LIGHT_TRAILS') {
            await cam.setInputSource('SIM_TRAFFIC');
            this.syncScenarioDropdown('SIM_TRAFFIC');
          } else if (mode === 'SILKY_WATER') {
            await cam.setInputSource('SIM_WATERFALL');
            this.syncScenarioDropdown('SIM_WATERFALL');
          } else if (mode === 'CROWD_ERASER') {
            await cam.setInputSource('SIM_PLAZA');
            this.syncScenarioDropdown('SIM_PLAZA');
          }
        }
      });
    });
  }

  private syncScenarioDropdown(val: string): void {
    const select = document.querySelector<HTMLSelectElement>('#scenarioSelect');
    if (select) select.value = val;
  }
}
