import { WebGLPipeline } from '../gl/WebGLPipeline';
import { CameraManager } from '../camera/CameraManager';
import { HandheldStabilizer } from '../stabilization/HandheldStabilizer';
import type {
  ExposureMode,
  ShutterDuration,
  CaptureState,
  CameraSettings,
  CaptureProgress,
  CaptureResult,
  HistogramData
} from '../../types/camera';

export type ProgressCallback = (progress: CaptureProgress) => void;
export type ResultCallback = (result: CaptureResult) => void;
export type HistogramCallback = (data: HistogramData) => void;

export class LongExposureEngine {
  private readonly pipeline: WebGLPipeline;
  private readonly cameraManager: CameraManager;
  private readonly stabilizer: HandheldStabilizer;

  private state: CaptureState = 'IDLE';
  private mode: ExposureMode = 'LIGHT_TRAILS';
  private duration: ShutterDuration = 3;

  private settings: CameraSettings = {
    ev: 0.0,
    iso: 'AUTO',
    focusLocked: false,
    torch: false,
    stabilization: 'AI_OPTICAL',
    grid: true,
    colorProfile: 'LEICA_CLASSIC'
  };

  private isRunning = false;
  private animFrameId: number | null = null;

  // Exposure timing state
  private exposureStartTime = 0;
  private targetDurationMs = 3000;
  private frameCount = 0;
  private lastFpsCalcTime = 0;
  private currentFps = 60;
  private frameDeltaCounter = 0;
  private lastHistogramTime = 0;

  private onProgressListeners = new Set<ProgressCallback>();
  private onResultListeners = new Set<ResultCallback>();
  private onHistogramListeners = new Set<HistogramCallback>();

  constructor(canvas: HTMLCanvasElement) {
    this.pipeline = new WebGLPipeline(canvas);
    this.cameraManager = new CameraManager();
    this.stabilizer = new HandheldStabilizer();

    this.startLoop();
  }

  public getCameraManager(): CameraManager {
    return this.cameraManager;
  }

  public getStabilizer(): HandheldStabilizer {
    return this.stabilizer;
  }

  public getSettings(): CameraSettings {
    return this.settings;
  }

  public updateSettings(partial: Partial<CameraSettings>): void {
    this.settings = { ...this.settings, ...partial };
    if (partial.stabilization) {
      this.stabilizer.setMode(partial.stabilization);
    }
    if (partial.torch !== undefined) {
      this.cameraManager.toggleTorch(partial.torch).catch(() => {});
    }
  }

  public setMode(mode: ExposureMode): void {
    if (this.state === 'EXPOSING') return;
    this.mode = mode;
    this.pipeline.resetAccumulation();
  }

  public getMode(): ExposureMode {
    return this.mode;
  }

  public setDuration(duration: ShutterDuration): void {
    if (this.state === 'EXPOSING') return;
    this.duration = duration;
  }

  public getDuration(): ShutterDuration {
    return this.duration;
  }

  public getState(): CaptureState {
    return this.state;
  }

  public subscribeProgress(cb: ProgressCallback): () => void {
    this.onProgressListeners.add(cb);
    return () => this.onProgressListeners.delete(cb);
  }

  public subscribeResult(cb: ResultCallback): () => void {
    this.onResultListeners.add(cb);
    return () => this.onResultListeners.delete(cb);
  }

  public subscribeHistogram(cb: HistogramCallback): () => void {
    this.onHistogramListeners.add(cb);
    return () => this.onHistogramListeners.delete(cb);
  }

  /**
   * Start long-exposure capture
   */
  public startExposure(): void {
    if (this.state === 'EXPOSING') {
      // If in BULB mode and pressed again, stop exposure
      if (this.duration === 'BULB') {
        this.finishExposure();
      }
      return;
    }

    this.state = 'EXPOSING';
    this.frameCount = 0;
    this.exposureStartTime = performance.now();
    this.pipeline.resetAccumulation();
    this.stabilizer.reset();

    if (this.duration === 'BULB') {
      this.targetDurationMs = 0;
    } else {
      this.targetDurationMs = this.duration * 1000;
    }
  }

  public stopExposure(): void {
    if (this.state === 'EXPOSING') {
      this.finishExposure();
    }
  }

  private finishExposure(): void {
    this.state = 'PROCESSING';
    const elapsed = (performance.now() - this.exposureStartTime) / 1000;

    // Small micro-delay for post-processing display
    requestAnimationFrame(() => {
      const { width, height } = this.cameraManager.getDimensions();
      const { beforeUrl, afterUrl } = this.pipeline.captureResultDataUrls(this.settings);

      const result: CaptureResult = {
        id: `lumina_${Date.now()}`,
        timestamp: Date.now(),
        mode: this.mode,
        durationSeconds: Number(elapsed.toFixed(1)),
        frameCount: Math.max(1, this.frameCount),
        beforeDataUrl: beforeUrl,
        afterDataUrl: afterUrl,
        width,
        height,
        settings: { ...this.settings }
      };

      this.state = 'COMPLETED';
      this.onResultListeners.forEach((cb) => cb(result));

      // After dispatching result, reset state to idle
      setTimeout(() => {
        this.state = 'IDLE';
        this.pipeline.resetAccumulation();
      }, 500);
    });
  }

  private startLoop(): void {
    this.isRunning = true;

    const render = (time: number) => {
      if (!this.isRunning) return;

      // Calculate FPS
      this.frameDeltaCounter++;
      if (time - this.lastFpsCalcTime >= 1000) {
        this.currentFps = this.frameDeltaCounter;
        this.frameDeltaCounter = 0;
        this.lastFpsCalcTime = time;
      }

      const frameSource = this.cameraManager.getFrameSource(time);
      const isExposing = this.state === 'EXPOSING';

      // Handheld stabilization offset
      const offset = this.stabilizer.computeOffset(time, isExposing);

      if (isExposing) {
        // Accumulate into WebGL FBO pipeline
        this.pipeline.accumulateFrame(frameSource, this.mode, this.frameCount, offset);
        this.frameCount++;

        const elapsedMs = time - this.exposureStartTime;
        const elapsedSec = elapsedMs / 1000;

        let progressPercent = 0;
        if (this.targetDurationMs > 0) {
          progressPercent = Math.min(100, (elapsedMs / this.targetDurationMs) * 100);
        } else {
          // Bulb mode: continuous pulsing indicator
          progressPercent = (elapsedSec % 1.0) * 100;
        }

        const progress: CaptureProgress = {
          state: this.state,
          mode: this.mode,
          targetSeconds: this.duration === 'BULB' ? 0 : this.duration,
          elapsedSeconds: Number(elapsedSec.toFixed(1)),
          progressPercent,
          frameCount: this.frameCount,
          fps: this.currentFps
        };

        this.onProgressListeners.forEach((cb) => cb(progress));

        // Render current accumulation to screen in real time!
        this.pipeline.renderToCanvas(this.settings, false);

        // Check completion for fixed durations
        if (this.targetDurationMs > 0 && elapsedMs >= this.targetDurationMs) {
          this.finishExposure();
        }
      } else {
        // IDLE Live Viewfinder: upload and render current frame cleanly
        this.pipeline.accumulateFrame(frameSource, this.mode, 0, offset);
        this.pipeline.renderToCanvas(this.settings, false);
      }

      // Live Histogram updates at ~10-15 fps
      if (time - this.lastHistogramTime > 80 && this.onHistogramListeners.size > 0) {
        this.lastHistogramTime = time;
        const hist = this.pipeline.computeHistogram(12);
        this.onHistogramListeners.forEach((cb) => cb(hist));
      }

      this.animFrameId = requestAnimationFrame(render);
    };

    this.animFrameId = requestAnimationFrame(render);
  }

  public destroy(): void {
    this.isRunning = false;
    if (this.animFrameId !== null) {
      cancelAnimationFrame(this.animFrameId);
    }
    this.pipeline.destroy();
    this.cameraManager.destroy();
    this.onProgressListeners.clear();
    this.onResultListeners.clear();
    this.onHistogramListeners.clear();
  }
}
