import { ICONS } from '../icons';
import type { LongExposureEngine } from '../../core/engine/LongExposureEngine';
import type { ShutterDuration, CaptureProgress, CaptureResult } from '../../types/camera';

export class ShutterArea {
  private readonly container: HTMLElement;
  private readonly engine: LongExposureEngine;
  private readonly onOpenLastCapture: () => void;
  private lastResult: CaptureResult | null = null;

  private shutterRing: HTMLElement | null = null;
  private thumbImg: HTMLImageElement | null = null;
  private thumbEmpty: HTMLElement | null = null;

  constructor(engine: LongExposureEngine, onOpenLastCapture: () => void) {
    this.engine = engine;
    this.onOpenLastCapture = onOpenLastCapture;
    this.container = document.createElement('div');
    this.container.className = 'shutter-panel';
    this.render();
    this.initSubscriptions();
  }

  public getElement(): HTMLElement {
    return this.container;
  }

  public setLastResult(result: CaptureResult): void {
    this.lastResult = result;
    if (this.thumbImg && this.thumbEmpty) {
      this.thumbImg.src = result.afterDataUrl;
      this.thumbImg.style.display = 'block';
      this.thumbEmpty.style.display = 'none';
    }
  }

  private render(): void {
    const currentDuration = this.engine.getDuration();

    this.container.innerHTML = `
      <!-- Duration Selector: 3s | 5s | 9s | BULB -->
      <div class="duration-selector">
        <button class="duration-chip ${currentDuration === 3 ? 'active' : ''}" data-dur="3">3s</button>
        <button class="duration-chip ${currentDuration === 5 ? 'active' : ''}" data-dur="5">5s</button>
        <button class="duration-chip ${currentDuration === 9 ? 'active' : ''}" data-dur="9">9s</button>
        <button class="duration-chip ${currentDuration === 'BULB' ? 'active' : ''}" data-dur="BULB">BULB</button>
      </div>

      <!-- Shutter Row -->
      <div class="shutter-row">
        <!-- Gallery Thumbnail -->
        <button class="btn-gallery-thumb" id="btnGallery" title="Review Last Capture">
          <img id="thumbImg" style="display: none;" alt="Last Capture" />
          <div class="thumb-empty" id="thumbEmpty">
            ${ICONS.film}
          </div>
        </button>

        <!-- Leica Two-Stage Metallic Shutter Button -->
        <div class="shutter-outer-ring" id="shutterBtn" title="Press to Expose">
          <div class="shutter-inner-btn">
            <div class="shutter-center-dot"></div>
          </div>
        </div>

        <!-- Film / Color Profile shortcut -->
        <button class="btn-extra-ctrl" id="btnProfilesQuick" title="Color Profile">
          ${ICONS.sliders}
        </button>
      </div>
    `;

    this.shutterRing = this.container.querySelector<HTMLElement>('#shutterBtn');
    this.thumbImg = this.container.querySelector<HTMLImageElement>('#thumbImg');
    this.thumbEmpty = this.container.querySelector<HTMLElement>('#thumbEmpty');

    this.attachEvents();
  }

  private attachEvents(): void {
    // Duration chips
    const chips = this.container.querySelectorAll<HTMLElement>('.duration-chip');
    chips.forEach((chip) => {
      chip.addEventListener('click', () => {
        const raw = chip.dataset.dur;
        const dur: ShutterDuration = raw === 'BULB' ? 'BULB' : (parseInt(raw || '3', 10) as 3 | 5 | 9);
        this.engine.setDuration(dur);
        chips.forEach((c) => c.classList.toggle('active', c === chip));
      });
    });

    // Shutter button click
    this.shutterRing?.addEventListener('click', () => {
      if (this.engine.getState() === 'EXPOSING') {
        this.engine.stopExposure();
      } else {
        this.engine.startExposure();
      }
    });

    // Gallery Thumbnail
    const btnGallery = this.container.querySelector<HTMLElement>('#btnGallery');
    btnGallery?.addEventListener('click', () => {
      if (this.lastResult) {
        this.onOpenLastCapture();
      }
    });

    // Color Profiles Quick Button
    const btnProfilesQuick = this.container.querySelector<HTMLElement>('#btnProfilesQuick');
    btnProfilesQuick?.addEventListener('click', () => {
      const btnProfileToggle = document.querySelector<HTMLElement>('#btnProfileToggle');
      btnProfileToggle?.click();
    });
  }

  private initSubscriptions(): void {
    this.engine.subscribeProgress((progress: CaptureProgress) => {
      if (progress.state === 'EXPOSING') {
        this.shutterRing?.classList.add('exposing');
      } else {
        this.shutterRing?.classList.remove('exposing');
      }
    });
  }
}
