import { ICONS } from '../icons';
import type { LongExposureEngine } from '../../core/engine/LongExposureEngine';
import type { InputSource, ColorProfile } from '../../types/camera';

export class HeaderBar {
  private readonly container: HTMLElement;
  private readonly engine: LongExposureEngine;
  private readonly onOpenPricing: () => void;
  private isEvDrawerOpen = false;

  constructor(engine: LongExposureEngine, onOpenPricing: () => void) {
    this.engine = engine;
    this.onOpenPricing = onOpenPricing;
    this.container = document.createElement('div');
    this.render();
  }

  public getElement(): HTMLElement {
    return this.container;
  }

  private render(): void {
    const settings = this.engine.getSettings();

    this.container.innerHTML = `
      <div class="header-bar">
        <div class="brand-badge">
          <div class="brand-dot"></div>
          <span class="brand-text">LUMINA</span>
          <span class="brand-price-tag" id="btnPricingBadge">$2.49 LIFETIME</span>
        </div>

        <div class="header-controls">
          <button class="btn-icon-hdr ${settings.torch ? 'active' : ''}" id="btnTorch" title="Flash / Torch">
            ${settings.torch ? ICONS.flashOn : ICONS.flashOff}
          </button>
          <button class="btn-icon-hdr ${settings.grid ? 'active' : ''}" id="btnGrid" title="Composition Grid">
            ${ICONS.grid}
          </button>
          <button class="btn-icon-hdr ${settings.stabilization !== 'OFF' ? 'active' : ''}" id="btnStabilizer" title="Handheld Anti-Shake">
            ${ICONS.gyro}
          </button>
          <button class="btn-icon-hdr" id="btnPricing" title="App Info & Pricing">
            ${ICONS.info}
          </button>
        </div>
      </div>

      <div class="quick-controls">
        <div class="quick-control-item" id="btnEvToggle" title="Exposure Value (EV)">
          <span>EV</span>
          <span class="quick-val" id="evDisplay">${settings.ev >= 0 ? `+${settings.ev.toFixed(1)}` : settings.ev.toFixed(1)}</span>
        </div>

        <div class="quick-control-item" id="btnIsoToggle" title="ISO Sensitivity">
          <span>ISO</span>
          <span class="quick-val" id="isoDisplay">${settings.iso}</span>
        </div>

        <div class="quick-control-item" id="btnProfileToggle" title="Color Profile">
          <span class="quick-val" id="profileDisplay">${this.formatProfileName(settings.colorProfile)}</span>
        </div>

        <select class="scenario-select" id="scenarioSelect" title="Input Stream Source">
          <option value="SIM_TRAFFIC">Highway (Night)</option>
          <option value="SIM_WATERFALL">Waterfall (Rapid)</option>
          <option value="SIM_PLAZA">Plaza (Crowd)</option>
          <option value="LIVE_CAMERA">Device Camera</option>
        </select>
      </div>

      <div class="drawer-slider" id="evDrawer">
        <span style="font-family: var(--font-mono); font-size: 11px; color: var(--text-secondary); width: 44px;">-2.0 EV</span>
        <input type="range" class="ev-input" id="evSlider" min="-2.0" max="2.0" step="0.1" value="${settings.ev}" />
        <span style="font-family: var(--font-mono); font-size: 11px; color: var(--text-secondary); width: 44px; text-align: right;">+2.0 EV</span>
      </div>
    `;

    this.attachEvents();
  }

  private formatProfileName(p: ColorProfile): string {
    switch (p) {
      case 'LEICA_CLASSIC': return 'LEICA M';
      case 'HASSELBLAD_NATURAL': return 'HASSELBLAD';
      case 'MONOCHROM': return 'MONO';
      case 'VIVID': return 'VIVID';
    }
  }

  private attachEvents(): void {
    const btnPricingBadge = this.container.querySelector<HTMLElement>('#btnPricingBadge');
    const btnPricing = this.container.querySelector<HTMLElement>('#btnPricing');
    btnPricingBadge?.addEventListener('click', () => this.onOpenPricing());
    btnPricing?.addEventListener('click', () => this.onOpenPricing());

    // Torch / Flash
    const btnTorch = this.container.querySelector<HTMLElement>('#btnTorch');
    btnTorch?.addEventListener('click', () => {
      const current = this.engine.getSettings().torch;
      this.engine.updateSettings({ torch: !current });
      btnTorch.classList.toggle('active', !current);
      btnTorch.innerHTML = !current ? ICONS.flashOn : ICONS.flashOff;
    });

    // Composition Grid
    const btnGrid = this.container.querySelector<HTMLElement>('#btnGrid');
    btnGrid?.addEventListener('click', () => {
      const current = this.engine.getSettings().grid;
      this.engine.updateSettings({ grid: !current });
      btnGrid.classList.toggle('active', !current);
      const gridElem = document.querySelector('.grid-lines');
      if (gridElem) gridElem.classList.toggle('hidden', current);
    });

    // Handheld Anti-Shake Toggle
    const btnStabilizer = this.container.querySelector<HTMLElement>('#btnStabilizer');
    btnStabilizer?.addEventListener('click', () => {
      const current = this.engine.getSettings().stabilization;
      const next = current === 'AI_OPTICAL' ? 'OFF' : 'AI_OPTICAL';
      this.engine.updateSettings({ stabilization: next });
      btnStabilizer.classList.toggle('active', next !== 'OFF');
      const badge = document.querySelector<HTMLElement>('#stabBadge');
      if (badge) {
        badge.innerText = next === 'AI_OPTICAL' ? 'AI OPTICAL LOCKED' : 'STABILIZER OFF';
      }
    });

    // EV Drawer Toggle & Slider
    const btnEvToggle = this.container.querySelector<HTMLElement>('#btnEvToggle');
    const evDrawer = this.container.querySelector<HTMLElement>('#evDrawer');
    const evSlider = this.container.querySelector<HTMLInputElement>('#evSlider');
    const evDisplay = this.container.querySelector<HTMLElement>('#evDisplay');

    btnEvToggle?.addEventListener('click', () => {
      this.isEvDrawerOpen = !this.isEvDrawerOpen;
      evDrawer?.classList.toggle('open', this.isEvDrawerOpen);
    });

    evSlider?.addEventListener('input', () => {
      const val = parseFloat(evSlider.value);
      this.engine.updateSettings({ ev: val });
      if (evDisplay) {
        evDisplay.innerText = val >= 0 ? `+${val.toFixed(1)}` : val.toFixed(1);
      }
    });

    // ISO Cycle
    const btnIsoToggle = this.container.querySelector<HTMLElement>('#btnIsoToggle');
    const isoDisplay = this.container.querySelector<HTMLElement>('#isoDisplay');
    const isoValues: Array<number | 'AUTO'> = ['AUTO', 50, 100, 200, 400, 800];
    let isoIndex = 0;

    btnIsoToggle?.addEventListener('click', () => {
      isoIndex = (isoIndex + 1) % isoValues.length;
      const nextIso = isoValues[isoIndex];
      this.engine.updateSettings({ iso: nextIso });
      if (isoDisplay) isoDisplay.innerText = String(nextIso);
    });

    // Profile Cycle
    const btnProfileToggle = this.container.querySelector<HTMLElement>('#btnProfileToggle');
    const profileDisplay = this.container.querySelector<HTMLElement>('#profileDisplay');
    const profiles: ColorProfile[] = ['LEICA_CLASSIC', 'HASSELBLAD_NATURAL', 'MONOCHROM', 'VIVID'];
    let profileIndex = 0;

    btnProfileToggle?.addEventListener('click', () => {
      profileIndex = (profileIndex + 1) % profiles.length;
      const nextProf = profiles[profileIndex];
      this.engine.updateSettings({ colorProfile: nextProf });
      if (profileDisplay) profileDisplay.innerText = this.formatProfileName(nextProf);
    });

    // Scenario / Input Stream Selector
    const scenarioSelect = this.container.querySelector<HTMLSelectElement>('#scenarioSelect');
    scenarioSelect?.addEventListener('change', async () => {
      const src = scenarioSelect.value as InputSource;
      await this.engine.getCameraManager().setInputSource(src);
    });
  }
}
