import { ICONS } from '../icons';
import type { CaptureResult } from '../../types/camera';

export class BeforeAfterModal {
  private readonly container: HTMLElement;
  private currentResult: CaptureResult | null = null;
  private isDragging = false;

  private beforeWrap: HTMLElement | null = null;
  private splitViewer: HTMLElement | null = null;

  constructor() {
    this.container = document.createElement('div');
    this.container.className = 'modal-backdrop';
    this.render();
  }

  public getElement(): HTMLElement {
    return this.container;
  }

  public open(result: CaptureResult): void {
    this.currentResult = result;
    this.populateData(result);
    this.container.classList.add('open');
  }

  public close(): void {
    this.container.classList.remove('open');
  }

  private render(): void {
    this.container.innerHTML = `
      <div class="modal-card">
        <div class="modal-header">
          <div class="modal-title">
            <span style="color: var(--leica-amber);">${ICONS.film}</span>
            <span>Computational Capture Review</span>
          </div>
          <button class="modal-close-btn" id="btnCloseModal">
            ${ICONS.close}
          </button>
        </div>

        <div class="modal-body">
          <!-- Interactive Before / After Split Slider -->
          <div class="split-viewer" id="splitViewer">
            <img class="split-img-after" id="imgAfter" alt="Long Exposure" />
            <div class="split-img-before-wrap" id="beforeWrap">
              <img class="split-img-before" id="imgBefore" alt="Raw Single Frame" />
              <div class="split-divider-handle" id="dividerHandle">❮❯</div>
            </div>
            <div class="split-tag split-tag-before">Single Shot</div>
            <div class="split-tag split-tag-after">Long Exposure</div>
          </div>

          <!-- Technical EXIF & Processing Telemetry -->
          <div class="exif-grid">
            <div class="exif-item">
              <span class="exif-label">MODE</span>
              <span class="exif-val" id="exifMode">LIGHT TRAILS</span>
            </div>
            <div class="exif-item">
              <span class="exif-label">EXPOSURE</span>
              <span class="exif-val" id="exifDuration">3.0s</span>
            </div>
            <div class="exif-item">
              <span class="exif-label">FRAMES STACKED</span>
              <span class="exif-val" id="exifFrames">180</span>
            </div>
            <div class="exif-item">
              <span class="exif-label">PROFILE</span>
              <span class="exif-val" id="exifProfile">LEICA M</span>
            </div>
            <div class="exif-item">
              <span class="exif-label">ISO / EV</span>
              <span class="exif-val" id="exifIso">AUTO / +0.0</span>
            </div>
            <div class="exif-item">
              <span class="exif-label">RESOLUTION</span>
              <span class="exif-val" id="exifRes">1280x720</span>
            </div>
          </div>

          <!-- Actions: Save full res to gallery & Share -->
          <div class="modal-actions">
            <button class="btn-primary-action" id="btnSaveGallery">
              ${ICONS.download}
              <span>Save Full Resolution</span>
            </button>
            <button class="btn-secondary-action" id="btnShareCapture">
              ${ICONS.share}
              <span>Share</span>
            </button>
          </div>
        </div>
      </div>
    `;

    this.splitViewer = this.container.querySelector<HTMLElement>('#splitViewer');
    this.beforeWrap = this.container.querySelector<HTMLElement>('#beforeWrap');

    this.attachEvents();
  }

  private populateData(result: CaptureResult): void {
    const imgBefore = this.container.querySelector<HTMLImageElement>('#imgBefore');
    const imgAfter = this.container.querySelector<HTMLImageElement>('#imgAfter');
    if (imgBefore) imgBefore.src = result.beforeDataUrl;
    if (imgAfter) imgAfter.src = result.afterDataUrl;

    const exifMode = this.container.querySelector<HTMLElement>('#exifMode');
    const exifDuration = this.container.querySelector<HTMLElement>('#exifDuration');
    const exifFrames = this.container.querySelector<HTMLElement>('#exifFrames');
    const exifProfile = this.container.querySelector<HTMLElement>('#exifProfile');
    const exifIso = this.container.querySelector<HTMLElement>('#exifIso');
    const exifRes = this.container.querySelector<HTMLElement>('#exifRes');

    if (exifMode) exifMode.innerText = result.mode.replace('_', ' ');
    if (exifDuration) exifDuration.innerText = `${result.durationSeconds}s`;
    if (exifFrames) exifFrames.innerText = `${result.frameCount} frames`;
    if (exifProfile) exifProfile.innerText = result.settings.colorProfile.replace('_', ' ');
    if (exifIso) exifIso.innerText = `${result.settings.iso} / ${result.settings.ev >= 0 ? `+${result.settings.ev}` : result.settings.ev}`;
    if (exifRes) exifRes.innerText = `${result.width}x${result.height}`;

    // Reset split position to 50%
    if (this.beforeWrap) {
      this.beforeWrap.style.width = '50%';
    }
  }

  private attachEvents(): void {
    const btnClose = this.container.querySelector<HTMLElement>('#btnCloseModal');
    btnClose?.addEventListener('click', () => this.close());

    // Interactive slider drag
    const onMove = (clientX: number) => {
      if (!this.splitViewer || !this.beforeWrap) return;
      const rect = this.splitViewer.getBoundingClientRect();
      const x = Math.max(0, Math.min(rect.width, clientX - rect.left));
      const percent = (x / rect.width) * 100;
      this.beforeWrap.style.width = `${percent}%`;
    };

    this.splitViewer?.addEventListener('mousedown', (e) => {
      this.isDragging = true;
      onMove(e.clientX);
    });

    window.addEventListener('mousemove', (e) => {
      if (this.isDragging) onMove(e.clientX);
    });

    window.addEventListener('mouseup', () => {
      this.isDragging = false;
    });

    // Touch support for mobile
    this.splitViewer?.addEventListener('touchstart', (e) => {
      this.isDragging = true;
      if (e.touches[0]) onMove(e.touches[0].clientX);
    }, { passive: true });

    window.addEventListener('touchmove', (e) => {
      if (this.isDragging && e.touches[0]) onMove(e.touches[0].clientX);
    }, { passive: true });

    window.addEventListener('touchend', () => {
      this.isDragging = false;
    });

    // Save to Gallery
    const btnSave = this.container.querySelector<HTMLElement>('#btnSaveGallery');
    btnSave?.addEventListener('click', () => {
      if (!this.currentResult) return;
      const a = document.createElement('a');
      a.href = this.currentResult.afterDataUrl;
      a.download = `LuminaShutter_${this.currentResult.mode}_${this.currentResult.id}.jpg`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);

      const span = btnSave.querySelector('span');
      if (span) {
        const orig = span.innerText;
        span.innerText = 'Saved to Photos!';
        setTimeout(() => { span.innerText = orig; }, 2000);
      }
    });

    // Share
    const btnShare = this.container.querySelector<HTMLElement>('#btnShareCapture');
    btnShare?.addEventListener('click', async () => {
      if (!this.currentResult) return;
      if (navigator.share) {
        try {
          const blob = await (await fetch(this.currentResult.afterDataUrl)).blob();
          const file = new File([blob], `LuminaShutter_${this.currentResult.id}.jpg`, { type: 'image/jpeg' });
          await navigator.share({
            title: 'LuminaShutter Computational Long Exposure',
            text: `Shot with LuminaShutter (${this.currentResult.mode.replace('_', ' ')} • ${this.currentResult.durationSeconds}s • Zero Subscription)`,
            files: [file]
          });
        } catch {
          // ignore or fall back
        }
      } else {
        navigator.clipboard?.writeText(window.location.href);
        const span = btnShare.querySelector('span');
        if (span) {
          const orig = span.innerText;
          span.innerText = 'Link Copied!';
          setTimeout(() => { span.innerText = orig; }, 2000);
        }
      }
    });
  }
}
